const CACHE='auralis-frontier-v4-horizons';
const FILES=['./','./classic.html','./sectors.js','./horizons.js','./horizons-render.js','./horizons-ui.js','./horizons-art.js','./horizons.css','./world-storage.js','./index.html','./styles.css','./app.js','./engine.js','./terrain.js','./renderer.js','./world.js','./art.js','./assets/art/shipyard-v3.png','./frontier.js','./frontier-ui.js','./assets/art/military-buildings-v3.png','./assets/art/military-troops-v3.png','./assets/art/historical-troops-v3.png','./assets/art/buildings.png','./assets/art/troops.png','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('auralis-frontier-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!FILES.some(f=>new URL(f,self.registration.scope).pathname===url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(cached=>cached||new Response('Sin conexión. Abre el juego en línea una vez para descargarlo.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}}))));});
